267	    /**
268	     * Count the owners that already exist (before this create) sharing the same first name and last
269	     * name as {@code owner}, compared case-insensitively. Returns zero when the owner's name is
270	     * unique among the existing owners.
271	     */
272	    private int countNamesakes(Owner owner) {
273	        String firstName = owner.getFirstName();
274	        String lastName = owner.getLastName();
275	        if (firstName == null || lastName == null) {
276	            return 0;
277	        }
278	        return (int) ownerRepository.findAll().stream()
279	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
280	                && lastName.equalsIgnoreCase(existing.getLastName()))
281	            .count();
282	    }
