284	    /**
285	     * Find the owners that already belong to the same household as {@code owner}, i.e. have the same
286	     * last name and the same address. Last names are compared case-insensitively with collapsed
287	     * whitespace; addresses are compared in their canonical normalized form (see
288	     * {@link AddressNormalizer}), so differences in letter case, runs of spaces or street-type
289	     * abbreviations are ignored. Returns an empty list when the owner has no last name or address to
290	     * match on.
291	     */
292	    private List<Owner> findHouseholdMembers(Owner owner) {
293	        String lastName = normalizeHouseholdKey(owner.getLastName());
294	        String address = AddressNormalizer.normalize(owner.getAddress());
295	        if (lastName == null || address == null) {
296	            return List.of();
