304	    /**
305	     * Resolve the stable {@code householdId} shared by a household. If any existing member already
306	     * carries one it is reused so the identifier stays stable as further owners join; otherwise a
307	     * new one is generated. The resolved value is back-filled onto every member that is missing it
308	     * (or has a different one) so all members of the household share the same identifier.
309	     */
310	    private String resolveHouseholdId(List<Owner> members) {
311	        String householdId = members.stream()
312	            .map(Owner::getHouseholdId)
313	            .filter(id -> id != null && !id.isBlank())
314	            .findFirst()
315	            .orElseGet(() -> UUID.randomUUID().toString());
316	        for (Owner member : members) {
317	            if (!householdId.equals(member.getHouseholdId())) {
318	                member.setHouseholdId(householdId);
