336	     * 4-digit zero-padded sequence equal to one more than the current number of owners
337	     * (e.g. {@code 'SMI-0007'}).
338	     */
339	    private String generateCustomerCode(Owner owner) {
340	        String lastName = owner.getLastName();
341	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
342	        long sequence = ownerRepository.findAll().size() + 1L;
343	        return String.format("%s-%04d", last3, sequence);
344	    }
