348	     * last two digits of the owner's {@code registrationDate} year (e.g. {@code 'SMI-0007-M26'}).
349	     */
350	    private String generateMembershipNumber(Owner owner) {
351	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
352	        return String.format("%s-M%s", owner.getCustomerCode(), yy);
353	    }
